  "src/App.jsx": "import React from 'react';
import { Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import Header from './components/Header';
import Footer from './components/Footer';
import Dashboard from './screens/Dashboard';
import StoryWorld from './screens/StoryWorld';
import PuzzleZone from './screens/PuzzleZone';
import LearningArcade from './screens/LearningArcade';
import ProgressJournal from './screens/ProgressJournal';
import ParentPortal from './screens/ParentPortal';
import Profile from './screens/Profile';

function App() {
  return (
    <div className="flex flex-col min-h-screen bg-gray-100">
      <Header />
      <Navbar />
      <main className="flex-grow container mx-auto p-4">
        <Routes>
          <Route path="/" element={<Dashboard />} />
          <Route path="/story-world" element={<StoryWorld />} />
          <Route path="/puzzle-zone" element={<PuzzleZone />} />
          <Route path="/learning-arcade" element={<LearningArcade />} />
          <Route path="/progress-journal" element={<ProgressJournal />} />
          <Route path="/parent-portal" element={<ParentPortal />} />
          <Route path="/profile" element={<Profile />} />
        </Routes>
      </main>
      <Footer />
    </div>
  );
}

export default App;
