  "src/store/slices/userProfileSlice.js": "import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  userId: 'guest_user',
  username: 'Guest',
  avatar: 'default.png',
  email: '',
};

const userProfileSlice = createSlice({
  name: 'userProfile',
  initialState,
  reducers: {
    setUserProfile: (state, action) => {
      state.userId = action.payload.userId || state.userId;
      state.username = action.payload.username || state.username;
      state.avatar = action.payload.avatar || state.avatar;
      state.email = action.payload.email || state.email;
    },
    resetUserProfile: (state) => {
      Object.assign(state, initialState);
    },
  },
});

export const { setUserProfile, resetUserProfile } = userProfileSlice.actions;

export default userProfileSlice.reducer;
",
  "src/store/slices/learningProgressSlice.js": "import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  storyCompletion: { 'story-1': false, 'story-2': false },
  puzzleCompletion: { 'puzzle-1': false, 'puzzle-2': false },
  gameScores: { 'game-1': 0, 'game-2': 0 },
  mathLevel: 1,
  scienceLevel: 1,
};

const learningProgressSlice = createSlice({
  name: 'learningProgress',
  initialState,
  reducers: {
    markStoryComplete: (state, action) => {
      state.storyCompletion[action.payload.storyId] = true;
    },
    markPuzzleComplete: (state, action) => {
      state.puzzleCompletion[action.payload.puzzleId] = true;
    },
    updateGameScore: (state, action) => {
      const { gameId, score } = action.payload;
      if (score > state.gameScores[gameId]) {
        state.gameScores[gameId] = score;
      }
    },
    increaseMathLevel: (state) => {
      state.mathLevel += 1;
    },
    increaseScienceLevel: (state) => {
      state.scienceLevel += 1;
    },
    resetLearningProgress: (state) => {
      Object.assign(state, initialState);
    },
  },
});

export const {
  markStoryComplete,
  markPuzzleComplete,
  updateGameScore,
  increaseMathLevel,
  increaseScienceLevel,
  resetLearningProgress,
} = learningProgressSlice.actions;

export default learningProgressSlice.reducer;
