  "src/store/slices/engagementMetricsSlice.js": "import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  totalTimeSpent: 0, // in seconds
  storiesViewed: 0,
  puzzlesAttempted: 0,
  gamesPlayed: 0,
  lastActivity: null, // timestamp
};

const engagementMetricsSlice = createSlice({
  name: 'engagementMetrics',
  initialState,
  reducers: {
    addTimeSpent: (state, action) => {
      state.totalTimeSpent += action.payload; // payload is time in seconds
      state.lastActivity = Date.now();
    },
    incrementStoriesViewed: (state) => {
      state.storiesViewed += 1;
      state.lastActivity = Date.now();
    },
    incrementPuzzlesAttempted: (state) => {
      state.puzzlesAttempted += 1;
      state.lastActivity = Date.now();
    },
    incrementGamesPlayed: (state) => {
      state.gamesPlayed += 1;
      state.lastActivity = Date.now();
    },
    resetEngagementMetrics: (state) => {
      Object.assign(state, initialState);
    },
  },
});

export const {
  addTimeSpent,
  incrementStoriesViewed,
  incrementPuzzlesAttempted,
  incrementGamesPlayed,
  resetEngagementMetrics,
} = engagementMetricsSlice.actions;

export default engagementMetricsSlice.reducer;
