  "src/screens/StoryWorld.jsx": "import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { markStoryComplete } from '../store/slices/learningProgressSlice';
import { incrementStoriesViewed } from '../store/slices/engagementMetricsSlice';
import { v4 as uuidv4 } from 'uuid';

function StoryWorld() {
  const dispatch = useDispatch();
  const storyCompletion = useSelector((state) => state.learningProgress.storyCompletion);
  const username = useSelector((state) => state.userProfile.username);

  const stories = [
    { id: 'story-1', title: 'The Magical Forest Adventure', description: 'Explore a land filled with enchanted creatures.', content: 'Long ago, in a land of magic...' },
    { id: 'story-2', title: 'Journey to the Stars', description: 'Blast off into space and discover new planets.', content: 'One starry night, a young astronaut...' },
  ];

  const handleStoryComplete = (storyId) => {
    if (!storyCompletion[storyId]) {
      dispatch(markStoryComplete({ storyId }));
      dispatch(incrementStoriesViewed());
      alert(`Congratulations, ${username}! You completed '${stories.find(s => s.id === storyId).title}'!`);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-100 to-indigo-100 p-8 rounded-lg shadow-xl">
      <h2 className="text-4xl font-bold text-blue-800 mb-6 text-center">Story World</h2>
      <p className="text-lg text-gray-700 mb-8 text-center">Dive into AI-generated interactive stories. Choose your adventure!</p>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {stories.map((story) => (
          <div key={story.id} className="bg-white p-6 rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300 transform hover:-translate-y-1 relative">
            {storyCompletion[story.id] && (
              <span className="absolute top-3 right-3 bg-green-500 text-white text-xs font-semibold px-2 py-1 rounded-full">Completed</span>
            )}
            <h3 className="text-2xl font-semibold text-blue-700 mb-2">{story.title}</h3>
            <p className="text-gray-600 mb-4">{story.description}</p>
            <p className="text-sm text-gray-500 italic">{story.content.substring(0, 50)}...</p>
            <button
              onClick={() => handleStoryComplete(story.id)}
              className={`mt-4 w-full px-4 py-2 rounded-lg text-white font-semibold transition-colors duration-300 
                ${storyCompletion[story.id] ? 'bg-gray-400 cursor-not-allowed' : 'bg-blue-500 hover:bg-blue-600'}`}
              disabled={storyCompletion[story.id]}
            >
              {storyCompletion[story.id] ? 'Story Completed' : 'Read Story'}
            </button>
          </div>
        ))}
      </div>

      <div className="mt-12 p-6 bg-yellow-50 rounded-lg border-l-4 border-yellow-500 text-yellow-800">
        <h4 className="font-bold text-xl mb-2">Voice-based Reading Companion</h4>
        <p>A voice-based reading companion feature would be integrated here to read stories aloud and assist children with pronunciation.</p>
        <p className="mt-2 text-sm">This section is for illustrative purposes; the actual voice feature requires more advanced integration.</p>
      </div>
    </div>
  );
}

export default StoryWorld;
