  "src/screens/PuzzleZone.jsx": "import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { markPuzzleComplete } from '../store/slices/learningProgressSlice';
import { incrementPuzzlesAttempted } from '../store/slices/engagementMetricsSlice';
import { v4 as uuidv4 } from 'uuid';

function PuzzleZone() {
  const dispatch = useDispatch();
  const puzzleCompletion = useSelector((state) => state.learningProgress.puzzleCompletion);
  const username = useSelector((state) => state.userProfile.username);

  const puzzles = [
    { id: 'puzzle-1', title: 'Shape Shifters', description: 'Match the shapes and colors!', difficulty: 'Easy' },
    { id: 'puzzle-2', title: 'Number Sequence', description: 'Find the missing numbers in the series.', difficulty: 'Medium' },
    { id: 'puzzle-3', title: 'Word Scramble', description: 'Unscramble the letters to form words.', difficulty: 'Hard' },
  ];

  const handlePuzzleAttempt = (puzzleId) => {
    // Simulate attempting a puzzle
    dispatch(incrementPuzzlesAttempted());
    // For demonstration, immediately mark as complete
    if (Math.random() > 0.3) { // Simulate 70% chance of success
      dispatch(markPuzzleComplete({ puzzleId }));
      alert(`Great job, ${username}! You solved '${puzzles.find(p => p.id === puzzleId).title}'!`);
    } else {
      alert(`Keep trying, ${username}! You'll get '${puzzles.find(p => p.id === puzzleId).title}' next time!`);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-100 to-pink-100 p-8 rounded-lg shadow-xl">
      <h2 className="text-4xl font-bold text-purple-800 mb-6 text-center">Puzzle Zone</h2>
      <p className="text-lg text-gray-700 mb-8 text-center">Challenge your mind with engaging puzzles designed to boost your skills.</p>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {puzzles.map((puzzle) => (
          <div key={puzzle.id} className="bg-white p-6 rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300 transform hover:-translate-y-1 relative">
             {puzzleCompletion[puzzle.id] && (
              <span className="absolute top-3 right-3 bg-green-500 text-white text-xs font-semibold px-2 py-1 rounded-full">Completed</span>
            )}
            <h3 className="text-2xl font-semibold text-purple-700 mb-2">{puzzle.title}</h3>
            <p className="text-gray-600 mb-4">{puzzle.description}</p>
            <p className="text-sm text-gray-500 italic">Difficulty: {puzzle.difficulty}</p>
            <button
              onClick={() => handlePuzzleAttempt(puzzle.id)}
              className={`mt-4 w-full px-4 py-2 rounded-lg text-white font-semibold transition-colors duration-300 
                ${puzzleCompletion[puzzle.id] ? 'bg-gray-400 cursor-not-allowed' : 'bg-purple-500 hover:bg-purple-600'}`}
              disabled={puzzleCompletion[puzzle.id]}
            >
              {puzzleCompletion[puzzle.id] ? 'Puzzle Solved' : 'Start Puzzle'}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default PuzzleZone;
