  "src/screens/Profile.jsx": "import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { setUserProfile, resetUserProfile } from '../store/slices/userProfileSlice';
import { v4 as uuidv4 } from 'uuid';

function Profile() {
  const dispatch = useDispatch();
  const currentUserProfile = useSelector((state) => state.userProfile);

  const [username, setUsername] = useState(currentUserProfile.username);
  const [email, setEmail] = useState(currentUserProfile.email);
  const [avatar, setAvatar] = useState(currentUserProfile.avatar);

  useEffect(() => {
    setUsername(currentUserProfile.username);
    setEmail(currentUserProfile.email);
    setAvatar(currentUserProfile.avatar);
  }, [currentUserProfile]);

  const handleSaveProfile = (e) => {
    e.preventDefault();
    dispatch(setUserProfile({ username, email, avatar }));
    alert('Profile updated successfully!');
  };

  const handleResetProfile = () => {
    dispatch(resetUserProfile());
    alert('Profile reset to default!');
  };

  const avatarOptions = [
    'https://api.dicebear.com/7.x/pixel-art/svg?seed=Buddy',
    'https://api.dicebear.com/7.x/pixel-art/svg?seed=Mittens',
    'https://api.dicebear.com/7.x/pixel-art/svg?seed=Felix',
    'https://api.dicebear.com/7.x/pixel-art/svg?seed=Cali'
