import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  storyCompletion: { 'story-1': false, 'story-2': false },
  puzzleCompletion: { 'puzzle-1': false, 'puzzle-2': false },
  gameScores: { 'game-1': 0, 'game-2': 0 },
  mathLevel: 1,
  scienceLevel: 1,
};

const learningProgressSlice = createSlice({
  name: 'learningProgress',
  initialState,
  reducers: {
    markStoryComplete: (state, action) => {
      state.storyCompletion[action.payload.storyId] = true;
    },
    markPuzzleComplete: (state, action) => {
      state.puzzleCompletion[action.payload.puzzleId] = true;
    },
    updateGameScore: (state, action) => {
      const { gameId, score } = action.payload;
      if (score > state.gameScores[gameId]) {
        state.gameScores[gameId] = score;
      }
    },
    increaseMathLevel: (state) => {
      state.mathLevel += 1;
    },
    increaseScienceLevel: (state) => {
      state.scienceLevel += 1;
    },
    resetLearningProgress: (state) => {
      Object.assign(state, initialState);
    },
  },
});

export const {
  markStoryComplete,
  markPuzzleComplete,
  updateGameScore,
  increaseMathLevel,
  increaseScienceLevel,
  resetLearningProgress,
} = learningProgressSlice.actions;

export default learningProgressSlice.reducer;

import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  totalTimeSpent: 0, // in seconds
  storiesViewed: 0,
  puzzlesAttempted: 0,
  gamesPlayed: 0,
  lastActivity: null, // timestamp
};

const engagementMetricsSlice = createSlice({
  name: 'engagementMetrics',
  initialState,
  reducers: {
    addTimeSpent: (state, action) => {
      state.totalTimeSpent += action.payload; // payload is time in seconds
      state.lastActivity = Date.now();
    },
    incrementStoriesViewed: (state) => {
      state.storiesViewed += 1;
      state.lastActivity = Date.now();
    },
    incrementPuzzlesAttempted: (state) => {
      state.puzzlesAttempted += 1;
      state.lastActivity = Date.now();
    },
    incrementGamesPlayed: (state) => {
      state.gamesPlayed += 1;
      state.lastActivity = Date.now();
    },
    resetEngagementMetrics: (state) => {
      Object.assign(state, initialState);
    },
  },
});

export const {
  addTimeSpent,
  incrementStoriesViewed,
  incrementPuzzlesAttempted,
  incrementGamesPlayed,
  resetEngagementMetrics,
} = engagementMetricsSlice.actions;

export default engagementMetricsSlice.reducer;

