import React from 'react';
import { useSelector } from 'react-redux';

function ProgressJournal() {
  const userProfile = useSelector((state) => state.userProfile);
  const learningProgress = useSelector((state) => state.learningProgress);
  const engagementMetrics = useSelector((state) => state.engagementMetrics);

  const totalStories = Object.keys(learningProgress.storyCompletion).length;
  const completedStories = Object.values(learningProgress.storyCompletion).filter(Boolean).length;

  const totalPuzzles = Object.keys(learningProgress.puzzleCompletion).length;
  const completedPuzzles = Object.values(learningProgress.puzzleCompletion).filter(Boolean).length;

  const formatTime = (seconds) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `${h}h ${m}m ${s}s`;
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-yellow-50 to-amber-50 p-8 rounded-lg shadow-xl">
      <h2 className="text-4xl font-bold text-yellow-800 mb-6 text-center">Progress Journal for {userProfile.username}</h2>
      <p className="text-lg text-gray-700 mb-8 text-center">Track your achievements and see how much you've learned!</p>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-10">
        <div className="bg-white p-6 rounded-lg shadow-md border-t-4 border-yellow-500">
          <h3 className="text-2xl font-semibold text-yellow-700 mb-4">Learning Achievements</h3>
          <ul className="list-disc list-inside text-gray-700 space-y-2">
            <li><span className="font-medium">Stories Completed:</span> {completedStories} / {totalStories}</li>
            <li><span className="font-medium">Puzzles Solved:</span> {completedPuzzles} / {totalPuzzles}</li>
            <li><span className="font-medium">Math Level:</span> {learningProgress.mathLevel}</li>
            <li><span className="font-medium">Science Level:</span> {learningProgress.scienceLevel}</li>
            {Object.entries(learningProgress.gameScores).map(([gameId, score]) => (
              <li key={gameId}><span className="font-medium">Highest Score ({gameId}):</span> {score}</li>
            ))}
          </ul>
        </div>

        <div className="bg-white p-6 rounded-lg shadow-md border-t-4 border-teal-500">
          <h3 className="text-2xl font-semibold text-teal-700 mb-4">Engagement Overview</h3>
          <ul className="list-disc list-inside text-gray-700 space-y-2">
            <li><span className="font-medium">Total Time Spent:</span> {formatTime(engagementMetrics.totalTimeSpent)}</li>
            <li><span className="font-medium">Stories Viewed:</span> {engagementMetrics.storiesViewed}</li>
            <li><span className="font-medium">Puzzles Attempted:</span> {engagementMetrics.puzzlesAttempted}</li>
            <li><span className="font-medium">Games Played:</span> {engagementMetrics.gamesPlayed}</li>
            <li><span className="font-medium">Last Activity:</span> {engagementMetrics.lastActivity ? new Date(engagementMetrics.lastActivity).toLocaleString() : 'N/A'}</li>
          </ul>
        </div>
      </div>

      <div className="bg-blue-50 p-6 rounded-lg border-l-4 border-blue-500 text-blue-800">
        <h4 className="font-bold text-xl mb-2">Detailed Insights (Future Enhancement)</h4>
        <p>This section will eventually provide more granular insights, charts, and personalized recommendations based on your learning patterns and engagement data.</p>
      </div>
    </div>
  );
}

export default ProgressJournal;

