import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  userId: 'guest_user',
  username: 'Guest',
  avatar: 'default.png',
  email: '',
};

const userProfileSlice = createSlice({
  name: 'userProfile',
  initialState,
  reducers: {
    setUserProfile: (state, action) => {
      state.userId = action.payload.userId || state.userId;
