import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { updateGameScore, increaseMathLevel, increaseScienceLevel } from '../store/slices/learningProgressSlice';
import { incrementGamesPlayed } from '../store/slices/engagementMetricsSlice';
import { v4 as uuidv4 } from 'uuid';

function LearningArcade() {
  const dispatch = useDispatch();
  const gameScores = useSelector((state) => state.learningProgress.gameScores);
  const mathLevel = useSelector((state) => state.learningProgress.mathLevel);
  const scienceLevel = useSelector((state) => state.learningProgress.scienceLevel);
  const username = useSelector((state) => state.userProfile.username);
  const [difficulty, setDifficulty] = useState('easy');

  const games = [
    { id: 'game-1', title: 'Math Whiz', description: 'Solve quick math problems!', type: 'quiz' },
    { id: 'game-2', title: 'Science Explorer', description: 'Test your knowledge about the natural world!', type: 'quiz' },
    { id: 'game-3', title: 'Word Search', description: 'Find hidden words in the grid.', type: 'game' },
    { id: 'game-4', title: 'Multiplayer Challenge', description: 'Compete with friends in a safe environment.', type: 'multiplayer' },
  ];

  const handlePlayGame = (gameId, gameType) => {
    dispatch(incrementGamesPlayed());
    const score = Math.floor(Math.random() * 100) + 1;
    dispatch(updateGameScore({ gameId, score }));
    alert(`Nice job, ${username}! You played '${games.find(g => g.id === gameId).title}' and scored ${score} points!`);

    if (gameType === 'quiz') {
      if (gameId === 'game-1' && score > 70) {
        dispatch(increaseMathLevel());
      } else if (gameId === 'game-2' && score > 70) {
        dispatch(increaseScienceLevel());
      }
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-red-100 to-orange-100 p-8 rounded-lg shadow-xl">
      <h2 className="text-4xl font-bold text-red-800 mb-6 text-center">Learning Arcade</h2>
      <p className="text-lg text-gray-700 mb-8 text-center">Play fun games, quizzes, and safe multiplayer challenges!</p>

      <div className="mb-8 p-4 bg-orange-50 rounded-lg border-l-4 border-orange-500 text-orange-800">
        <h4 className="font-bold text-xl mb-2">Adaptive Difficulty Levels</h4>
        <p className="mb-2">Difficulty for math and science quizzes adapts based on performance. Your current levels are: Math Level {mathLevel}, Science Level {scienceLevel}.</p>
        <label htmlFor="difficulty" className="font-medium">Select Quiz Difficulty:</label>
        <select 
          id="difficulty" 
          value={difficulty} 
          onChange={(e) => setDifficulty(e.target.value)}
          className="ml-2 p-2 border border-orange-300 rounded-md bg-white text-gray-700"
        >
          <option value="easy">Easy</option>
          <option value="medium">Medium</option>
          <option value="hard">Hard</option>
        </select>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
        {games.map((game) => (
          <div key={game.id} className="bg-white p-6 rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300 transform hover:-translate-y-1">
            <h3 className="text-2xl font-semibold text-red-700 mb-2">{game.title}</h3>
            <p className="text-gray-600 mb-4">{game.description}</p>
            <p className="text-sm text-gray-500 italic">Highest Score: {gameScores[game.id] || 0}</p>
            <button
              onClick={() => handlePlayGame(game.id, game.type)}
              className="mt-4 w-full bg-red-500 text-white px-4 py-2 rounded-lg hover:bg-red-600 transition-colors font-semibold"
            >
              {game.type === 'multiplayer' ? 'Join Challenge' : 'Play Now'}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default LearningArcade;

