import React from 'react';
import { useSelector } from 'react-redux';

function ProgressJournal() {
  const userProfile = useSelector((state) => state.userProfile);
  const learningProgress = useSelector((state) => state.learningProgress);
  const engagementMetrics = useSelector((state) => state.engagementMetrics);

  const totalStories = Object.keys(learningProgress.storyCompletion).length;
