import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { setUserProfile, resetUserProfile } from '../store/slices/userProfileSlice';
import { v4 as uuidv4 } from 'uuid';

function Profile() {
  const dispatch = useDispatch();
  const currentUserProfile = useSelector((state) => state.userProfile);

  const [username, setUsername] = useState(currentUserProfile.username);
  const [email, setEmail] = useState(currentUserProfile.email);
  const [avatar, setAvatar] = useState(currentUserProfile.avatar);

  useEffect(() => {
    setUsername(currentUserProfile.username);
    setEmail(currentUserProfile.email);
    setAvatar(currentUserProfile.avatar);
  }, [currentUserProfile]);

  const handleSaveProfile = (e) => {
    e.preventDefault();
    dispatch(setUserProfile({ username, email, avatar }));
    alert('Profile updated successfully!');
  };

  const handleResetProfile = () => {
    dispatch(resetUserProfile());
    alert('Profile reset to default!');
  };

  const avatarOptions = [
    'https://api.dicebear.com/7.x/pixel-art/svg?seed=Buddy',
    'https://api.dicebear.com/7.x/pixel-art/svg?seed=Mittens',
    'https://api.dicebear.com/7.x/pixel-art/svg?seed=Felix',
    'https://api.dicebear.com/7.x/pixel-art/svg?seed=Cali'
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-50 to-purple-50 p-8 rounded-lg shadow-xl">
      <h2 className="text-4xl font-bold text-indigo-800 mb-6 text-center">My Profile</h2>
      <p className="text-lg text-gray-700 mb-8 text-center">Manage your personal details and customize your experience.</p>

      <div className="max-w-xl mx-auto bg-white p-8 rounded-lg shadow-md border-t-4 border-indigo-500">
        <div className="flex flex-col items-center mb-6">
          <img 
            src={avatar || 'https://api.dicebear.com/7.x/pixel-art/svg?seed=default'}
            alt="User Avatar"
            className="w-32 h-32 rounded-full border-4 border-indigo-300 object-cover mb-4 shadow-lg"
          />
          <h3 className="text-2xl font-semibold text-indigo-700">{username}</h3>
        </div>

        <form onSubmit={handleSaveProfile} className="space-y-6">
          <div>
            <label htmlFor="username" className="block text-gray-700 text-sm font-medium mb-2">Username:</label>
            <input
              type="text"
              id="username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-400 focus:border-transparent transition duration-200"
              required
            />
          </div>

          <div>
            <label htmlFor="email" className="block text-gray-700 text-sm font-medium mb-2">Email:</label>
            <input
              type="email"
              id="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-400 focus:border-transparent transition duration-200"
            />
          </div>

          <div>
            <label htmlFor="avatar" className="block text-gray-700 text-sm font-medium mb-2">Choose Avatar:</label>
            <div className="flex flex-wrap gap-4">
              {avatarOptions.map((optAvatar) => (
                <img
                  key={uuidv4()}
                  src={optAvatar}
                  alt="Avatar option"
                  className={`w-16 h-16 rounded-full border-2 cursor-pointer transition-all duration-200 
                    ${avatar === optAvatar ? 'border-indigo-600 ring-2 ring-indigo-300 transform scale-110' : 'border-gray-300 hover:border-indigo-400'}`}
                  onClick={() => setAvatar(optAvatar)}
                />
              ))}
            </div>
          </div>

          <div className="flex flex-col sm:flex-row space-y-4 sm:space-y-0 sm:space-x-4">
            <button
              type="submit"
              className="flex-1 bg-indigo-600 text-white p-3 rounded-lg font-semibold hover:bg-indigo-700 transition-colors duration-200 shadow-md"
            >
              Save Profile
            </button>
            <button
              type="button"
              onClick={handleResetProfile}
              className="flex-1 bg-red-500 text-white p-3 rounded-lg font-semibold hover:bg-red-600 transition-colors duration-200 shadow-md"
            >
              Reset to Default
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default Profile;
